'use strict';
// The shared cases (sdk/cases, generated by the Rust SDK's tests; sdk/rust/README.md, "The
// shared cases"). For every case and run, this test starts itself as a child process (fresh
// SDK state) once through the CommonJS and once through the ESM entry; the child makes the
// case's calls through hydo-assert and hydo-assert/history, and the parent compares what the
// sink received and what the calls returned with the case's files.
//
//   node --test          (in sdk/js; runs every file in test/)
//
// JavaScript has no float32, and its strings cannot hold invalid UTF-8 bytes for a history
// record (a lone surrogate is written as U+FFFD there), so cases that need "f32" or "raw_hist"
// are skipped (and reported). Invalid UTF-8 in assertion details is a lone surrogate here.
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawn } = require('child_process');

const CASES = path.join(__dirname, '..', '..', 'cases');
const PRE = 'PRE existing line\n';
const UNSUPPORTED = {
  f32: 'JavaScript has no float32',
  raw_hist: 'JavaScript strings cannot hold the invalid UTF-8 bytes of a history record',
};
const KNOWN = new Set(['f32', 'bytes', 'invalid_utf8', 'raw_hist', 'emit_line']);

// ---- the child ----

function str(x) {
  if (typeof x === 'string') return x;
  return x.raw.map((p) => (typeof p === 'string' ? p : String.fromCharCode(0xdc00 + p))).join('');
}

function int(t) {
  const n = Number(t);
  return Number.isSafeInteger(n) ? n : BigInt(t);
}

function val(x) {
  if (x === null || typeof x === 'boolean' || typeof x === 'string') return x;
  if (Array.isArray(x)) return x.map(val);
  const [tag, y] = Object.entries(x)[0];
  switch (tag) {
    case 'int':
    case 'uint':
      return int(y);
    case 'f64':
      return { NaN: NaN, '+Inf': Infinity, '-Inf': -Infinity }[y] ?? Number(y);
    case 'raw':
      return str(x);
    case 'bytes':
      return Uint8Array.from(Buffer.from(y, 'hex'));
    case 'map': {
      const o = {};
      for (const [k, v] of y) o[str(k)] = val(v);
      return o;
    }
  }
  throw new Error('value tag ' + tag);
}

function details(st) {
  return 'details' in st ? val(st.details) : undefined;
}

function arg(x, h) {
  if (typeof x === 'string' || 'raw' in x) return str(x);
  const [tag, y] = Object.entries(x)[0];
  switch (tag) {
    case 'enc': return h.enc(str(y));
    case 'ver': return h.ver(str(y[0]), int(y[1]));
    case 'value_or_nil': return h.valueOrNil(y === null ? null : str(y));
    case 'list': return h.list(...y.map(str));
    case 'append_mop': return h.append(str(y[0]), str(y[1]));
    case 'read_mop': return h.read(str(y));
    case 'read_result_mop': return h.readResult(str(y[0]), ...y[1].map(str));
    case 'nil': return h.NIL;
  }
  throw new Error('argument tag ' + tag);
}

const CAMEL = {
  greater_than: 'greaterThan',
  greater_than_or_equal_to: 'greaterThanOrEqualTo',
  less_than: 'lessThan',
  less_than_or_equal_to: 'lessThanOrEqualTo',
};

async function child() {
  const esm = process.env.HYDO_JS_ENTRY === 'esm';
  const ha = esm ? await import('../index.mjs') : require('..');
  const h = esm ? await import('../history.mjs') : require('../history.js');
  const c = JSON.parse(fs.readFileSync(process.env.HYDO_CASE_FILE, 'utf8'));
  const objs = [];
  const watches = [];
  const hists = [];
  const ops = [];
  let ret = '';
  const push = (b) => { ret += b ? '1' : '0'; };
  const args = (st) => st.args.map((a) => arg(a, h));
  const decl = {
    always: ha.always,
    always_or_unreachable: ha.alwaysOrUnreachable,
    sometimes: ha.sometimes,
    reachable: ha.reachable,
    unreachable: ha.unreachable,
  };
  for (const st of c.steps) {
    const d = st.do;
    if (d in decl) objs.push(decl[d](str(st.id), str(st.msg)));
    else if (d === 'eventually') objs.push(ha.eventually(str(st.id), str(st.msg), st.within_ms));
    else if (d === 'buggify') objs.push(ha.buggify(str(st.id), str(st.msg)));
    else if (d === 'check') push(objs[st.a].check(st.cond, details(st)));
    else if (d === 'hit') objs[st.a].hit(details(st));
    else if (d === 'cmp') {
      const a = objs[st.a];
      let left = val(st.left);
      let right = val(st.right);
      if (typeof left !== typeof right) { left = BigInt(left); right = BigInt(right); }
      push(st.helper ? a[CAMEL[st.helper]](left, right, details(st)) : a.cmp(left, st.op, right, details(st)));
    } else if (d === 'begin') watches.push(objs[st.a].begin());
    else if (d === 'done') push(watches[st.w].done(details(st)));
    else if (d === 'expire') watches[st.w].expire(details(st));
    else if (d === 'await') {
      const l = objs[st.a];
      push(st.async ? await l.awaitCond(() => true, 1, details(st)) : l.awaitCondSync(() => true, 1, details(st)));
    } else if (d === 'fire') push(objs[st.a].fire(details(st)));
    else if (d === 'catalog') ha.catalog();
    else if (d === 'setup_complete') ha.setupComplete();
    else if (d === 'emit_line') ha.emitLine(st.tag, val(st.value));
    else if (d === 'history') hists.push(new h.History(st.name));
    else if (d === 'invoke') ops.push(hists[st.h].invoke(val(st.proc), st.f, ...args(st)));
    else if (d === 'ok') ops[st.o].ok(...args(st));
    else if (d === 'ok_same') ops[st.o].ok();
    else if (d === 'fail') ops[st.o].fail();
    else if (d === 'info') ops[st.o].info();
    else if (d === 'record') hists[st.h].record(val(st.proc), st.type, st.f, ...args(st));
    else throw new Error('unknown step ' + d + ': update this test');
  }
  fs.writeFileSync(process.env.HYDO_CASE_RETURNS, ret);
}

// ---- the parent ----

function maskTimes(b) {
  const out = [];
  let prev = -1n;
  const lines = b.toString('latin1').split(/(?<=\n)/);
  for (let line of lines) {
    if (line.startsWith('HYDO-HIST ')) {
      const f = line.split(' ');
      const rest = f.slice(5).join(' ');
      if (f.length < 6 || !/^[0-9]+$/.test(f[4]) || BigInt(f[4]) < prev) throw new Error('bad time field in ' + JSON.stringify(line));
      prev = BigInt(f[4]);
      line = f.slice(0, 4).concat(['*', rest]).join(' ');
    }
    out.push(line);
  }
  return Buffer.from(out.join(''), 'latin1');
}

function firstDifference(want, got) {
  const w = want.toString('utf8').split('\n');
  const g = got.toString('utf8').split('\n');
  for (let i = 0; i < Math.max(w.length, g.length); i++) {
    if (w[i] !== g[i]) return `line ${i + 1}:\n    case: ${JSON.stringify(w[i])}\n    js:   ${JSON.stringify(g[i])}`;
  }
  return '(equal)';
}

// Runs one run of a case in a child process; resolves to [output bytes, returns].
async function runCase(file, run, entry) {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'hydo-jscase-'));
  try {
    const env = {};
    for (const [k, v] of Object.entries(process.env)) if (!k.startsWith('HYDO_') && !k.startsWith('NODE_TEST')) env[k] = v;
    env.HYDO_CASE_FILE = file;
    env.HYDO_CASE_RETURNS = path.join(tmp, 'returns');
    env.HYDO_JS_ENTRY = entry;
    if (run.buggify_env !== null) env.HYDO_BUGGIFY = run.buggify_env;
    if (run.buggify_file !== null) {
      fs.writeFileSync(path.join(tmp, 'buggify'), run.buggify_file);
      env.HYDO_BUGGIFY_FILE = path.join(tmp, 'buggify');
    } else {
      env.HYDO_BUGGIFY_FILE = path.join(tmp, 'no-buggify');
    }
    const consolePath = path.join(tmp, 'console');
    const hist = path.join(tmp, 'hist');
    const { out, hist_out: hout } = run;
    if (out === 'file' || out === 'append') {
      fs.writeFileSync(consolePath, out === 'append' ? PRE : '');
      env.HYDO_ASSERT_OUT = consolePath;
    } else if (out === 'stderr' || out === 'off') env.HYDO_ASSERT_OUT = out;
    else if (out === 'missing') env.HYDO_ASSERT_OUT = path.join(tmp, 'missing');
    else throw new Error('out ' + out);
    if (hout === 'file' || hout === 'append') {
      fs.writeFileSync(hist, hout === 'append' ? PRE : '');
      env.HYDO_HIST_OUT = hist;
    } else if (hout === 'create') env.HYDO_HIST_OUT = hist;
    else if (hout === 'stderr' || hout === 'off') env.HYDO_HIST_OUT = hout;
    else if (hout === 'fallback') env.HYDO_HIST_OUT = path.join(tmp, 'no-such-dir', 'hist');
    else throw new Error('hist_out ' + hout);
    const p = await new Promise((resolve, reject) => {
      const c = spawn(process.execPath, [__filename], { env });
      const so = [];
      const se = [];
      c.stdout.on('data', (b) => so.push(b));
      c.stderr.on('data', (b) => se.push(b));
      c.on('error', reject);
      c.on('close', (status) => resolve({ status, stdout: Buffer.concat(so), stderr: Buffer.concat(se) }));
    });
    if (p.status !== 0) throw new Error(`child failed (${p.status}):\n${p.stdout}${p.stderr}`);
    const toStderr = out === 'stderr' || out === 'missing' || hout === 'stderr' || hout === 'fallback';
    if (!toStderr && p.stderr.length) throw new Error('wrote to stderr: ' + JSON.stringify(p.stderr.toString()));
    let got = Buffer.alloc(0);
    if (toStderr) got = p.stderr;
    else if (out !== 'off') got = fs.readFileSync(consolePath);
    else if (hout !== 'off') got = fs.readFileSync(hist);
    return [maskTimes(got), fs.readFileSync(path.join(tmp, 'returns'), 'utf8')];
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
}

// A small pool: the children start at once, as many at a time as there are CPUs.
function pool(n) {
  let active = 0;
  const waiting = [];
  const next = () => {
    if (active >= n || !waiting.length) return;
    active++;
    const [fn, resolve, reject] = waiting.shift();
    fn().then(resolve, reject).finally(() => { active--; next(); });
  };
  return (fn) => new Promise((resolve, reject) => { waiting.push([fn, resolve, reject]); next(); });
}

function parent() {
  const { test } = require('node:test');
  const assert = require('node:assert');
  const files = [];
  for (const area of fs.readdirSync(CASES).sort()) {
    const dir = path.join(CASES, area);
    if (!fs.statSync(dir).isDirectory()) continue;
    for (const f of fs.readdirSync(dir).sort()) if (f.endsWith('.json')) files.push(path.join(dir, f));
  }
  const skipped = {};
  let runs = 0;
  const limit = pool(Math.max(2, os.availableParallelism ? os.availableParallelism() : os.cpus().length));
  test('the shared cases exist', () => assert.ok(files.length > 0, 'no cases in ' + CASES));
  for (const file of files) {
    const id = path.relative(CASES, file).replace(/\\/g, '/').replace(/\.json$/, '');
    const c = JSON.parse(fs.readFileSync(file, 'utf8'));
    const why = c.needs.filter((n) => n in UNSUPPORTED).map((n) => UNSUPPORTED[n])[0];
    // start this case's children now; the test below waits for them
    const results = why ? [] : c.runs.flatMap((run) => ['cjs', 'esm'].map((entry) => [run, entry, limit(() => runCase(file, run, entry))]));
    for (const [, , p] of results) p.catch(() => {}); // reported by the test
    test(id, { skip: why }, async () => {
      for (const n of c.needs) assert.ok(KNOWN.has(n), `needs ${n}: update this test`);
      for (const [run, entry, p] of results) {
        const want = fs.readFileSync(path.join(path.dirname(file), run.output));
        const [got, returns] = await p;
        assert.ok(got.equals(want), `${run.name || '(run)'} ${entry}: output differs from ${run.output}, ${firstDifference(want, got)}`);
        assert.strictEqual(returns, run.returns, `${run.name || '(run)'} ${entry}: returns differ`);
        runs++;
      }
    });
    if (why) skipped[why] = (skipped[why] || 0) + 1;
  }
  test('summary', () => {
    for (const [why, n] of Object.entries(skipped)) process.stderr.write(`shared cases: skipped ${n} cases: ${why}\n`);
    process.stderr.write(`shared cases: ${runs} runs (CommonJS and ESM) of ${files.length} case files\n`);
  });
}

if (process.env.HYDO_CASE_FILE) {
  child().catch((e) => {
    process.stderr.write(String(e && e.stack) + '\n');
    process.exit(1);
  });
} else {
  parent();
}
